import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const n = Number(input[0]);

function isPrime(x: number): boolean {
  if (x < 2) return false;
  // 約数があれば √x 以下に必ず 1 つある
  for (let d = 2; d * d <= x; d++) {
    if (x % d === 0) return false;
  }
  return true;
}
console.log(isPrime(n) ? "Yes" : "No");
